import { View, Text, Pressable, Animated, StyleSheet } from "react-native";
import { useRef } from "react";
import { registerRootComponent } from "expo";

function App() {
  const anim = useRef(new Animated.Value(0)).current;
  const reveal = () => {
    Animated.timing(anim, { toValue: 1, duration: 350 }).start();
  };
  const translateY = anim.interpolate({ inputRange: [0, 1], outputRange: [30, 0] });
  return (
    <View style={styles.s}>
      <Pressable nativeID="go" style={styles.b} onPress={reveal}><Text style={styles.t}>Үзүүлэх</Text></Pressable>
      <Animated.View nativeID="card" style={[styles.card, { opacity: anim, transform: [{ translateY }] }]}>
        <Text style={styles.name}>Нарны шил</Text>
      </Animated.View>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 24, padding: 24, alignItems: "center", justifyContent: "center" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
  card: { backgroundColor: "#fff", padding: 20, borderRadius: 16, elevation: 4 }, name: { fontSize: 18, fontWeight: "600" },
});

registerRootComponent(App);
